-- Google Drive OAuth and photo migration support (schema only; integration must be enabled after setup).
-- Store refresh_token_encrypted as AES-GCM ciphertext generated by the backend.
CREATE TABLE IF NOT EXISTS google_drive_credentials (
    id BIGSERIAL PRIMARY KEY,
    account_email VARCHAR(255),
    refresh_token_encrypted TEXT NOT NULL,
    root_folder_id VARCHAR(255),
    connected BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS photo_migration_log (
    id BIGSERIAL PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    photo_kind VARCHAR(30) NOT NULL CHECK (photo_kind IN ('PROFILE', 'MEMBER')),
    source_value_hash VARCHAR(64) NOT NULL,
    google_drive_file_id VARCHAR(255),
    status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'UPLOADED', 'VERIFIED', 'FAILED')),
    attempts INTEGER NOT NULL DEFAULT 0,
    error_message TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(user_id, photo_kind, source_value_hash)
);

CREATE INDEX IF NOT EXISTS idx_photo_migration_status ON photo_migration_log(status);
